export type RegionId =
  | "north"
  | "northeast"
  | "central"
  | "east"
  | "west"
  | "south";

export const MAP_W = 452.99;
export const MAP_H = 830;

/** ค่าที่ใช้ตอนฉายพิกัด — ต้องใช้ชุดเดียวกันเวลาวางหมุดจาก lat/lng */
export const PROJECTION = {
  minLng: 97.35140100100011,
  maxLng: 105.65099776200009,
  minLat: 5.629890035000074,
  maxLat: 20.445006409000143,
  kx: 0.974223,
  scale: 56.0239,
};

export function project(lng: number, lat: number): [number, number] {
  const { minLng, maxLat, kx, scale } = PROJECTION;
  return [(lng - minLng) * kx * scale, (maxLat - lat) * scale];
}

export type ProvinceShape = {
  id: string;
  name: string;
  nameEn: string;
  region: RegionId;
  /** เส้นขอบจังหวัดในระบบพิกัดของ SVG */
  d: string;
  /** จุดวางป้ายชื่อ */
  label: [number, number];
  /** กรอบสี่เหลี่ยม [minX, minY, maxX, maxY] ใช้คำนวณระยะซูม */
  bbox: [number, number, number, number];
};

